	}
	
	if($this->getRequestParameter('nit_cedula')){	
	 	$c->add(ContratoPeer::NIT_CEDULA,'%'.$this->getRequestParameter('nit_cedula').'%',Criteria::LIKE);		
		$parametros.="&nit_cedula=".$this->getRequestParameter('nit_cedula');			 	
	}
	if($this->getRequestParameter('objeto')){	
	 	$c->add(ContratoPeer::OBJETO,'%'.$this->getRequestParameter('objeto').'%',Criteria::LIKE);
		$parametros.="&objeto=".$this->getRequestParameter('objeto');			 	
	}
	
	if($this->getRequestParameter('cdp')){	
