		$parametros.="&observaciones=".$this->getRequestParameter('observaciones');			 	
	}
	
	if ($this->getRequestParameter('fechaInicioInicial')) {
        $c->add(ContratoPeer::FECHA_INICIO, $this->getRequestParameter('fechaInicioInicial'),Criteria::GREATER_EQUAL);      
