  public function executeShow()
  { 
  	$currentForm="contrato/show";
  	$this->verificaPrilegioCerrar($currentForm); 	
  	$parametroDirFisicaDig = ParametroPeer::retrieveByPk(25);
	$parametroDirApacheDig = ParametroPeer::retrieveByPk(26);
	$parametroFormatoDig = ParametroPeer::retrieveByPk(31);
  	$dirFisicaDig=$parametroDirFisicaDig->getValortexto();
	$formatoDig=$this->formatoDig=$parametroFormatoDig->getValortexto();	
	$this->dirApacheDig=$parametroDirApacheDig->getValortexto();
	
    $contrato=$this->contrato = ContratoPeer::retrieveByPk($this->getRequestParameter('contrato_id'));
    $this->forward404Unless($this->contrato);
	
	if(file_exists($dirFisicaDig."CONTRATO".$contrato->getPrimaryKey().".".$formatoDig)){
		$this->digitalizado=1;
	}
	else{
		$this->digitalizado=0;
	}
	
    
  }

